'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isNegativeZerof = require( '@stdlib/math/base/assert/is-negative-zerof' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var tryRequire = require( '@stdlib/utils/try-require' );


// FIXTURES //

var x1 = require( './fixtures/julia/x_-0.5_0.5.json' );
var x2 = require( './fixtures/julia/x_-0.5_-0.75.json' );
var x3 = require( './fixtures/julia/x_0.5_0.75.json' );
var x4 = require( './fixtures/julia/x_0.75_0.9998.json' );
var x5 = require( './fixtures/julia/x_0.9998_0.99999.json' );
var x6 = require( './fixtures/julia/x_0.99999_1.json' );


// VARIABLES //

var erfinvf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( erfinvf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof erfinvf, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN`, the function returns `NaN`', opts, function test( t ) {
	var y = erfinvf( NaN );
	t.strictEqual( isnanf( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided `1`, the function returns `+infinity`', opts, function test( t ) {
	var y = erfinvf( 1.0 );
	t.strictEqual( y, PINF, 'returns expected value' );
	t.end();
});

tape( 'if provided `-1`, the function returns `-infinity`', opts, function test( t ) {
	var y = erfinvf( -1.0 );
	t.strictEqual( y, NINF, 'returns expected value' );
	t.end();
});

tape( 'if provided `-0`, the function returns `-0`', opts, function test( t ) {
	var y = erfinvf( -0.0 );
	t.strictEqual( isNegativeZerof( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided `+0`, the function returns `+0`', opts, function test( t ) {
	var y = erfinvf( 0.0 );
	t.strictEqual( isPositiveZerof( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided a value which is either less than `-1` or greater than `1`, the function returns `NaN`', opts, function test( t ) {
	var values;
	var y;
	var i;

	values = [
		f32( 3.14 ),
		f32( -3.14 ),
		f32( -1.1 ),
		f32( 1.1 ),
		PINF,
		NINF
	];

	for ( i = 0; i < values.length; i++ ) {
		y = erfinvf( values[ i ] );
		t.strictEqual( isnanf( y ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the inverse error function for `x` on the interval `[-0.5,0.5]`', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = x1.x;
	expected = x1.expected;
	for ( i = 0; i < x.length; i++ ) {
		y = erfinvf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 2 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the inverse error function for `x` on the interval `[-0.75,-0.5]`', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = x2.x;
	expected = x2.expected;
	for ( i = 0; i < x.length; i++ ) {
		y = erfinvf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 2 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the inverse error function for `x` on the interval `[0.5,0.75]`', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = x3.x;
	expected = x3.expected;
	for ( i = 0; i < x.length; i++ ) {
		y = erfinvf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 2 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the inverse error function for `x` on the interval `[0.75,0.9998]`', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = x4.x;
	expected = x4.expected;
	for ( i = 0; i < x.length; i++ ) {
		y = erfinvf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 3 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the inverse error function for `x` on the interval `[0.9998,0.99999]`', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = x5.x;
	expected = x5.expected;
	for ( i = 0; i < x.length; i++ ) {
		y = erfinvf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 2 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the inverse error function for `x` on the interval `[0.99999,1)`', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = x6.x;
	expected = x6.expected;
	for ( i = 0; i < x.length; i++ ) {
		y = erfinvf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});
